#!/usr/bin/env python3
"""Offline model/animation inspection, independent of any game save or unlock."""
from pathlib import Path
root=Path(__file__).resolve().parents[1]
files=['src/vendor/three.min.js','src/core.js','src/game/00-grid.js','src/game/01-data.js','src/game/characters-data.js','src/game/02-state.js','src/game/03-combat.js','src/game/models.js','src/game/models-mon.js','src/game/models-weapon.js','src/game/04-render.js','src/game/characters-assets.js','src/game/characters-render.js']
html='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Y2K 角色與動作審核</title><style>*{box-sizing:border-box}body{margin:0;background:#dfe5ee;color:#172751;font:16px/1.5 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:16px}h1{font-size:24px;margin:0}p{margin:8px 0}.controls{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0}button{font:inherit;min-height:44px;padding:6px 12px;color:inherit;border:1px solid #7b8ba4;background:#f2f4f7;cursor:pointer;border-radius:4px}button:hover{background:#cbd8ec}button[aria-pressed=true]{background:#303d9b;color:white}button:focus-visible{outline:3px solid #b94732;outline-offset:3px}canvas{display:block;width:100%;height:60vh;min-height:320px;max-height:650px;background:#bfcbd8;border:1px solid #7b8ba4}#status{min-height:24px}</style><main><h1>Y2K 角色與動作審核</h1><p>開發候選。此頁不讀寫遊戲進度；可切換角色、重播動作及檢查骨架。</p><div class="controls" id="characters" role="group" aria-label="角色"></div><div class="controls" id="actions" role="group" aria-label="動作"></div><canvas id="view" aria-label="角色 3D 預覽"></canvas><p id="status" role="status"></p><div class="controls"><button id="left">向左轉</button><button id="right">向右轉</button><button id="pause" aria-pressed="false">暫停動作</button><button id="bones" aria-pressed="false">顯示骨架</button><button id="wire" aria-pressed="false">顯示線框</button></div></main>'''
for file in files:html+='<script>\n'+(root/file).read_text()+'\n</script>'
html+='''<script>
(()=>{const canvas=document.getElementById('view'),status=document.getElementById('status');let rd;try{rd=new T3.WebGLRenderer({canvas,antialias:true});}catch(e){status.textContent='此瀏覽器未能啟動 WebGL，請以支援 WebGL 的瀏覽器開啟。';return;}rd.outputColorSpace=T3.SRGBColorSpace;rd.setPixelRatio(Math.min(devicePixelRatio,1.5));const scene=new T3.Scene();scene.add(new T3.HemisphereLight(0xeaf5ff,0xa3a9b0,1.6));const sun=new T3.DirectionalLight(0xfff6ed,1.4);sun.position.set(30,60,70);scene.add(sun);const cam=new T3.OrthographicCamera(-20,20,36,-4,.1,200);cam.position.set(0,18,90);cam.lookAt(0,18,0);let hero,helper,yaw=.3,paused=false,showBones=false,wire=false,action='idle';const names={idle:'待機',walk:'步行',run:'跑步',attack:'普通攻擊',cast:'施技',hurt:'受擊',dash:'閃避',death:'倒地',victory:'勝利'};
function refresh(){document.querySelectorAll('[data-character]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.character===G.char));document.querySelectorAll('[data-action]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.action===action));status.textContent=CHARS[G.char].n+'｜'+names[action]+'｜'+hero.userData.mesh.geometry.index.count/3+' 三角面｜16 根骨骼';}
function play(name){action=name;const u=hero.userData;if(u.actions[name]){u.animation='';characterPlay(hero,name,.08);}refresh();}
function choose(id){if(hero){characterDispose(hero);scene.remove(hero);scene.remove(helper);helper.dispose();}G.char=id;hero=buildY2KHero(0,0,0,0,{weaponStyle:'0',offhandStyle:'0',accessoryStyle:'0'});hero.scale.setScalar(1);scene.add(hero);hero.userData.mesh.material.wireframe=wire;helper=new T3.SkeletonHelper(hero);helper.visible=showBones;scene.add(helper);play(action);}
for(const [id,c]of Object.entries(CHARS)){const b=document.createElement('button');b.textContent=c.n;b.dataset.character=id;b.onclick=()=>choose(id);document.getElementById('characters').appendChild(b);}
for(const [id,label]of Object.entries(names)){const b=document.createElement('button');b.textContent=label;b.dataset.action=id;b.onclick=()=>play(id);document.getElementById('actions').appendChild(b);}
document.getElementById('left').onclick=()=>yaw-=Math.PI/8;document.getElementById('right').onclick=()=>yaw+=Math.PI/8;document.getElementById('pause').onclick=e=>{paused=!paused;e.target.setAttribute('aria-pressed',paused);e.target.textContent=paused?'播放動作':'暫停動作';};document.getElementById('bones').onclick=e=>{showBones=!showBones;helper.visible=showBones;e.target.setAttribute('aria-pressed',showBones);};document.getElementById('wire').onclick=e=>{wire=!wire;hero.userData.mesh.material.wireframe=wire;e.target.setAttribute('aria-pressed',wire);};choose('street');let last=performance.now();function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;const w=canvas.clientWidth,h=canvas.clientHeight;rd.setSize(w,h,false);cam.left=-21*w/h;cam.right=21*w/h;cam.top=39;cam.bottom=-3;cam.updateProjectionMatrix();if(!paused)hero.userData.mixer.update(dt);hero.rotation.y=yaw;if(hero.userData.pet){hero.userData.pet.position.set(8,13+Math.sin(now/350)*.6,-2);}rd.render(scene,cam);requestAnimationFrame(frame);}requestAnimationFrame(frame);
})();
</script></html>'''
(root/'dist/character-review.html').write_text(html)
print('wrote dist/character-review.html')
